package br.com.onda;
import android.app.Instrumentation;
import android.content.*;
import android.content.res.AssetFileDescriptor;
import android.media.*;
import android.net.Uri;
import android.os.*;
import android.provider.MediaStore;
import java.io.*;
import java.nio.ByteBuffer;
import java.security.MessageDigest;
import java.util.*;
import org.junit.*;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;

@androidx.media3.common.util.UnstableApi
public class FastConversionTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private final List<File> files=new ArrayList<>();private final List<Uri> rows=new ArrayList<>();private final Map<String,Map<String,?>> saved=new HashMap<>();
 private File temp(String suffix)throws Exception{File f=File.createTempFile("onda-fast-",suffix,c.getCacheDir());files.add(f);return f;}
 private File fixture(String name)throws Exception{File f=temp(".input");try(InputStream in=ins.getContext().getAssets().open(name);OutputStream out=new FileOutputStream(f)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}return f;}
 @Before public void before(){for(String p:Arrays.asList("downloads","downloaded_audio",DownloadHistory.PREF))saved.put(p,c.getSharedPreferences(p,0).getAll());}
 @After public void after()throws Exception{c.stopService(new Intent(c,MediaDownloadService.class));long until=SystemClock.elapsedRealtime()+5000;while(MediaDownloadService.activeDownload&&SystemClock.elapsedRealtime()<until)Thread.sleep(50);for(Uri row:rows)c.getContentResolver().delete(row,null,null);for(File f:files)f.delete();for(Map.Entry<String,Map<String,?>> p:saved.entrySet()){SharedPreferences.Editor e=c.getSharedPreferences(p.getKey(),0).edit().clear();for(Map.Entry<String,?> i:p.getValue().entrySet()){Object v=i.getValue();String k=i.getKey();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof Set)e.putStringSet(k,new HashSet<>((Set<String>)v));}e.commit();}}
 private byte[] aac(File f)throws Exception{MediaExtractor ex=new MediaExtractor();try{ex.setDataSource(f.getPath());int track=AudioTracks.aacTrack(ex);assertTrue(track>=0);ex.selectTrack(track);MessageDigest digest=MessageDigest.getInstance("SHA-256");ByteBuffer buffer=ByteBuffer.allocate(1024*1024);int count=0;while(true){buffer.clear();int n=ex.readSampleData(buffer,0);if(n<0)break;buffer.position(0);byte[] bytes=new byte[n];buffer.get(bytes);digest.update(bytes);count++;ex.advance();}assertTrue(count>10);return digest.digest();}finally{ex.release();}}
 @Test public void descriptorOffsetsPreserveAacAndExactMp3Encoding()throws Exception{File original=fixture("combined.mp4"),wrapped=temp(".wrapped"),m4a=temp(".m4a"),mp3=temp(".mp3"),legacy=temp(".mp3");try(OutputStream out=new FileOutputStream(wrapped);InputStream in=new FileInputStream(original)){out.write(new byte[128]);byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);out.write(new byte[256]);}ParcelFileDescriptor fd=ParcelFileDescriptor.open(wrapped,ParcelFileDescriptor.MODE_READ_ONLY);java.io.FileDescriptor raw=fd.getFileDescriptor();try(MediaInput.Direct direct=MediaInput.take(new AssetFileDescriptor(fd,128,original.length()))){assertNotNull(direct);assertEquals(128,direct.offset);assertEquals(original.length(),direct.length);LocalAudio.convertInput(direct,m4a,"m4a",320,()->{});assertArrayEquals(aac(original),aac(m4a));LocalAudio.convertInput(direct,mp3,"mp3",320,()->{});LocalAudio.convert(original,legacy,"mp3",320,()->{});assertArrayEquals(java.nio.file.Files.readAllBytes(legacy.toPath()),java.nio.file.Files.readAllBytes(mp3.toPath()));new Mp3ConverterTest().verify(mp3,1);}assertFalse(raw.valid());}
 @Test public void nonSeekableSourcesCloseAndDirectConversionCanBeCancelled()throws Exception{ParcelFileDescriptor[] pipe=ParcelFileDescriptor.createPipe();java.io.FileDescriptor raw=pipe[0].getFileDescriptor();try{assertNull(MediaInput.take(new AssetFileDescriptor(pipe[0],0,AssetFileDescriptor.UNKNOWN_LENGTH)));assertFalse(raw.valid());}finally{pipe[0].close();pipe[1].close();}File source=fixture("combined.mp4"),copy=temp(".import"),output=temp(".mp3");LocalAudio.importFile(c,Uri.fromFile(source),copy,()->{},n->{});assertArrayEquals(java.nio.file.Files.readAllBytes(source.toPath()),java.nio.file.Files.readAllBytes(copy.toPath()));try(MediaInput.Direct direct=MediaInput.open(c,Uri.fromFile(source))){assertNotNull(direct);int[] checks={0};try{LocalAudio.convertInput(direct,output,"mp3",192,()->{if(++checks[0]>5)throw new InterruptedIOException("cancelled");});fail("Direct conversion ignored cancellation");}catch(InterruptedIOException expected){}}assertTrue(source.exists());}
 private File service(Uri source,String format)throws Exception{File output=temp("."+format);String title="Fast native "+format;c.getSharedPreferences("downloads",0).edit().putString("status","").commit();Intent job=new Intent(c,MediaDownloadService.class).putExtra("conversion_source",source.toString()).putExtra("destination",Uri.fromFile(output).toString()).putExtra("format",format).putExtra("mp3_kbps",320).putExtra("title",title);ins.runOnMainSync(()->c.startForegroundService(job));long until=SystemClock.elapsedRealtime()+90000;String status="";while(SystemClock.elapsedRealtime()<until){status=c.getSharedPreferences("downloads",0).getString("status","");if(!MediaDownloadService.activeDownload&&status.startsWith("Conversão concluída"))break;if(!MediaDownloadService.activeDownload&&status.startsWith("Operação interrompida"))fail(status);Thread.sleep(100);}assertTrue(status,status.startsWith("Conversão concluída"));assertEquals("direct",c.getSharedPreferences("downloads",0).getString("conversion_read_mode",""));assertEquals(0,c.getSharedPreferences("downloads",0).getLong("conversion_import_bytes",-1));assertTrue(output.length()>0);return output;}
 @Test public void serviceReadsRealMediaStoreVideoWithoutImportingItsPadding()throws Exception{if(Build.VERSION.SDK_INT<29)return;File source=fixture("combined.mp4");ContentValues values=new ContentValues();values.put(MediaStore.MediaColumns.DISPLAY_NAME,"Onda-Fast-"+UUID.randomUUID()+".mp4");values.put(MediaStore.MediaColumns.MIME_TYPE,"video/mp4");values.put(MediaStore.MediaColumns.RELATIVE_PATH,Environment.DIRECTORY_MOVIES+"/OndaNative");values.put(MediaStore.MediaColumns.IS_PENDING,1);Uri row=c.getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,values);assertNotNull(row);rows.add(row);long padding=32L*1024*1024;try(OutputStream raw=c.getContentResolver().openOutputStream(row);DataOutputStream out=new DataOutputStream(new BufferedOutputStream(raw));InputStream in=new FileInputStream(source)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);out.writeInt((int)padding);out.writeBytes("free");Arrays.fill(b,(byte)0);for(long left=padding-8;left>0;){int size=(int)Math.min(left,b.length);out.write(b,0,size);left-=size;}}values.clear();values.put(MediaStore.MediaColumns.IS_PENDING,0);c.getContentResolver().update(row,values,null,null);File audio=service(row,"m4a");assertArrayEquals(aac(source),aac(audio));File mp3=service(row,"mp3");new Mp3ConverterTest().verify(mp3,1);try(AssetFileDescriptor descriptor=c.getContentResolver().openAssetFileDescriptor(row,"r")){assertNotNull(descriptor);assertTrue(descriptor.getLength()>=source.length()+padding);}try(OutputStream report=new FileOutputStream(new File(c.getFilesDir(),"fast-conversion-tests.json"))){report.write("{\"mediaStoreSource\":true,\"paddingBytes\":33554432,\"importedBytes\":0,\"aacPacketsPreserved\":true,\"mp3DecodedAudio\":true,\"offsetDescriptor\":true,\"fileAndDescriptorMp3Equal\":true}".getBytes("UTF-8"));}}
}
